get_cart:
query GetCart {
  getCart {
    id
    isUser
    shippingAddress {
      firstName
      lastName
      email
      phone
      __typename
    }
    lineItems {
      name
      quantity
      variant {
        sku
        prices {
          ... on CartLineItemVariantPrice {
            value {
              centAmount
              __typename
            }
            key
            __typename
          }
          __typename
        }
        attributesRaw {
          ... on CustomFieldRaw {
            name
            value
            __typename
          }
          ... on CustomFieldRawArray {
            name
            arrayValue: value
            __typename
          }
          ... on CustomFieldRawProduct {
            name
            productValue: value {
              typeId
              id
              __typename
            }
            __typename
          }
          ... on CustomFieldRawBrand {
            name
            brandValue: value {
              key
              label
              __typename
            }
            __typename
          }
          ... on CustomFieldRawKeyLabel {
            name
            keyLabel: value {
              key
              label
              __typename
            }
            __typename
          }
          ... on CustomFieldRawWholesalePrice {
            name
            wpValue: value {
              currencyCode
              centAmount
              fractionDigits
              type
              __typename
            }
            __typename
          }
          __typename
        }
        parentProduct {
          referencedResource {
            id
            key
            masterData {
              current {
                categories {
                  id
                  externalId
                  name
                  __typename
                }
                __typename
              }
              __typename
            }
            __typename
          }
          __typename
        }
        __typename
      }
      price {
        key
        value {
          centAmount
          __typename
        }
        custom {
          customFieldsRaw {
            name
            value {
              type
              currencyCode
              centAmount
              fractionDigits
              __typename
            }
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    couponDiscount {
      label
      centAmount
      __typename
    }
    rewardDiscount {
      label
      centAmount
      __typename
    }
    promotionalDiscount {
      label
      centAmount
      __typename
    }
    totalPrice {
      centAmount
      currencyCode
      fractionDigits
      type
      __typename
    }
    custom {
      customFieldsRaw {
        name
        value
        __typename
      }
      __typename
    }
    shippingInfo {
      price {
        centAmount
        __typename
      }
      discountedPrice {
        value {
          centAmount
          __typename
        }
        __typename
      }
      shippingMethod {
        id
        name
        key
        __typename
      }
      shippingRate {
        price {
          centAmount
          __typename
        }
        freeAbove {
          centAmount
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
  getAvailableShippingMethods {
    freeAbove
    key
    __typename
  }
}

get_product_inventory:
query GetProductInventory($input: ProductInventoryInput!) {
  productInventory(input: $input) {
    hasStock
    inventory {
      styleColor
      sizes {
        name
        sku
        stock {
          store {
            location
            stockLevel
            __typename
          }
          web {
            location
            stockLevel
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}
